import { HttpClient } from '@angular/common/http';
import { Injectable, inject } from '@angular/core';
import { Observable } from 'rxjs';

export interface ChecklistItem {
  id: number;
  taskId: number;
  text: string;
  done: boolean;
}

export interface Task {
  id: number;
  projectId: number;
  title: string;
  done: boolean;
  dueDate: string | null;
  assignee: string | null;
  checklist: ChecklistItem[];
}

@Injectable({ providedIn: 'root' })
export class TaskService {
  private readonly http = inject(HttpClient);

  listForProject(projectId: number): Observable<Task[]> {
    return this.http.get<Task[]>(`/api/projects/${projectId}/tasks`);
  }

  create(
    projectId: number,
    title: string,
    dueDate: string | null,
    assignee: string | null,
  ): Observable<Task> {
    return this.http.post<Task>(`/api/projects/${projectId}/tasks`, { title, dueDate, assignee });
  }

  toggle(projectId: number, taskId: number): Observable<Task> {
    return this.http.post<Task>(`/api/projects/${projectId}/tasks/${taskId}/toggle`, null);
  }

  addChecklistItem(projectId: number, taskId: number, text: string): Observable<ChecklistItem> {
    return this.http.post<ChecklistItem>(`/api/projects/${projectId}/tasks/${taskId}/checklist`, {
      text,
    });
  }

  toggleChecklistItem(projectId: number, taskId: number, itemId: number): Observable<ChecklistItem> {
    return this.http.post<ChecklistItem>(
      `/api/projects/${projectId}/tasks/${taskId}/checklist/${itemId}/toggle`,
      null,
    );
  }
}
import { Component, computed, inject, input, signal } from '@angular/core';
import { rxResource } from '@angular/core/rxjs-interop';
import { NonNullableFormBuilder, ReactiveFormsModule, Validators } from '@angular/forms';
import { TaskChecklist } from './task-checklist';
import { Task, TaskService } from './task.service';

export type TaskFilter = 'ALL' | 'OPEN' | 'DONE';

// A project's task list: add tasks and tick them off (OPEN <-> DONE) as they are finished.
@Component({
  selector: 'app-project-tasks',
  imports: [ReactiveFormsModule, TaskChecklist],
  template: `
    <section aria-labelledby="project-tasks-heading" data-testid="project-tasks">
      <h2 id="project-tasks-heading">Tasks</h2>

      <form [formGroup]="form" (ngSubmit)="submit()" data-testid="task-form" novalidate>
        <div>
          <label for="task-title">Task</label>
          <input
            id="task-title"
            type="text"
            formControlName="title"
            data-testid="task-form-title"
            [attr.aria-invalid]="showTitleError()"
            [attr.aria-describedby]="showTitleError() ? 'task-title-error' : null"
          />
          @if (showTitleError()) {
            <p id="task-title-error" role="alert" data-testid="task-form-title-error">
              Task is required.
            </p>
          }
        </div>
        <div>
          <label for="task-due-date">Due date (optional)</label>
          <input
            id="task-due-date"
            type="date"
            formControlName="dueDate"
            data-testid="task-form-due-date"
          />
        </div>
        <div>
          <label for="task-assignee">Assignee (optional)</label>
          <input
            id="task-assignee"
            type="text"
            formControlName="assignee"
            maxlength="255"
            data-testid="task-form-assignee"
          />
        </div>
        <button type="submit" data-testid="task-form-submit" [disabled]="saving()">Add task</button>
        @if (saveError()) {
          <p role="alert" data-testid="task-form-error">{{ saveError() }}</p>
        }
      </form>

      @if (toggleError()) {
        <p role="alert" data-testid="task-toggle-error">{{ toggleError() }}</p>
      }

      @if (tasks.error()) {
        <p role="alert" data-testid="project-tasks-error">Could not load the tasks.</p>
      } @else if (tasks.hasValue()) {
        @if (tasks.value().length === 0) {
          <p data-testid="project-tasks-empty">No tasks for this project yet.</p>
        } @else {
